#define HSIZE (1 << 21)

static long long hkey[HSIZE];
static int hcnt[HSIZE];

static inline long long hash_find_add(long long k) {
    unsigned long long h = (unsigned long long)k * 0x9E3779B97F4A7C15ULL;
    unsigned int i = (unsigned int)(h >> 40) & (HSIZE - 1);
